/*
 * locale_shim 的符号版本脚本。
 *
 * 预编译库（如 libng_gl4es.so）对 Android 8.0 才加入 bionic 的符号是按版本
 * 引用的，例如 `nl_langinfo@LIBC_O`；如果 shim 导出的符号没有版本定义，
 * Android 7 的 linker 会认为版本不匹配，dlopen 仍报 cannot locate symbol。
 *
 *  - nl_langinfo 在 locale_shim.c 中用 .symver 导出为非默认版本 @LIBC_O，
 *    这里只声明空的版本节点；
 *  - 其余 API 26/28 符号归入默认版本 LIBC。
 */
LIBC_O {
};

LIBC {
  global:
    nl_langinfo_l;
    newlocale;
    duplocale;
    freelocale;
    uselocale;
    pthread_setname_np;
    pthread_getname_np;
    memfd_create;
};
